const fs = require('fs');
const sources = [{ key: 'general', file: '/files/nexora-events.jsonl' }, { key: 'study', file: '/files/nexora-study.jsonl' }, { key: 'meetings', file: '/files/nexora-meetings.jsonl' }, { key: 'privacy', file: '/files/nexora-privacy-audit.jsonl' }];
const read = file => { if (!fs.existsSync(file)) return []; return fs.readFileSync(file, 'utf8').split('\n').filter(Boolean).map(line => { try { return JSON.parse(line); } catch { return null; } }).filter(Boolean); };
const data = Object.fromEntries(sources.map(s => [s.key, read(s.file)]));
const all = Object.values(data).flat();
const highPriority = data.general.filter(x => x.priority === 'alta').length;
const approvals = data.general.filter(x => x.approvalRequired).length;
const privacyAlerts = data.privacy.filter(x => x.score > 0).length;
const totals = Object.fromEntries(Object.entries(data).map(([key, value]) => [key, value.length]));
const activityScore = Math.min(100, all.length * 8);
return [{ json: { ok: true, workflow: 'panel-impacto', generatedAt: new Date().toISOString(), totalExecutions: all.length, totals, indicators: { highPriority, pendingHumanApproval: approvals, privacyAlerts, activityScore }, highlights: [`${data.study.length} planes de estudio adaptativos`, `${data.meetings.length} actas inteligentes`, `${data.privacy.length} revisiones de privacidad`, `${data.general.length} acciones del centro local`], recentActivity: all.slice(-5).reverse().map(x => ({ id: x.requestId || x.sessionId || x.meetingId || x.auditId, type: x.workflow || x.action || 'general', date: x.receivedAt || x.createdAt || x.date || x.checkedAt })) } }];
